<?php get_header(); while ( have_posts() ) : the_post(); $cafe_id = get_the_ID(); ?>
<main id="main" class="matin-detail" dir="rtl"><a class="matin-back" href="<?php echo esc_url( get_post_type_archive_link( 'matin_cafe' ) ); ?>">← همه کافه‌ها</a><article class="matin-detail-panel"><?php if ( has_post_thumbnail() ) : ?><div class="matin-detail-image"><?php the_post_thumbnail( 'large' ); ?></div><?php endif; ?><p class="matin-kicker">MATIN AI · CAFE</p><h1><?php the_title(); ?></h1><div class="matin-detail-copy"><?php the_content(); ?></div><dl class="matin-detail-facts"><dt>شهر / محله</dt><dd><?php echo esc_html( (string) get_post_meta( $cafe_id, '_matin_location', true ) ?: 'ثبت نشده' ); ?></dd><dt>نشانی</dt><dd><?php echo esc_html( (string) get_post_meta( $cafe_id, '_matin_address', true ) ?: 'ثبت نشده' ); ?></dd><dt>ساعت کاری</dt><dd><?php echo esc_html( (string) get_post_meta( $cafe_id, '_matin_opening_hours', true ) ?: 'برای ساعت کاری با کافه هماهنگ کنید' ); ?></dd><?php $map = (string) get_post_meta( $cafe_id, '_matin_map_url', true ); if ( $map && 0 === strpos( $map, 'https://' ) ) : ?><dt>موقعیت</dt><dd><a href="<?php echo esc_url( $map ); ?>" target="_blank" rel="noopener noreferrer">باز کردن نقشه</a></dd><?php endif; ?></dl><h2>برنامه‌های این کافه</h2><div class="matin-cafe-events"><?php $events = new WP_Query( [ 'post_type' => 'matin_event', 'post_status' => 'publish', 'posts_per_page' => 20, 'meta_query' => [ 'relation' => 'AND', [ 'key' => '_matin_cafe_id', 'value' => $cafe_id, 'compare' => '=' ], [ 'key' => '_matin_starts_at', 'compare' => 'EXISTS' ] ], 'meta_key' => '_matin_starts_at', 'orderby' => 'meta_value', 'order' => 'ASC' ] ); if ( $events->have_posts() ) : while ( $events->have_posts() ) : $events->the_post(); ?><a class="matin-cafe-event" href="<?php the_permalink(); ?>"><strong><?php the_title(); ?></strong><span><?php echo esc_html( (string) get_post_meta( get_the_ID(), '_matin_starts_at', true ) ); ?></span></a><?php endwhile; wp_reset_postdata(); else : ?><p>در حال حاضر برنامه منتشرشده‌ای برای این کافه ثبت نشده است.</p><?php endif; ?></div><a class="matin-catalog-cta" href="<?php echo esc_url( home_url( '/' ) ); ?>">پرسیدن از دستیار ماتین <span aria-hidden="true">←</span></a></article></main><?php endwhile; get_footer(); ?>
